"""EPIC protocol laboratory: replay / audit / export."""
import json
import math
import re
import sys

MAX_LINE = 32 * 1024 * 1024
VMAX_SNAP = 1 << 60


class Err(Exception):
    def __init__(self, cat):
        Exception.__init__(self, cat)
        self.cat = cat


def isint(x):
    return isinstance(x, int) and not isinstance(x, bool)


def chk(cond, cat):
    if not cond:
        raise Err(cat)


NAME_RE = re.compile(r"[A-Za-z][A-Za-z0-9_]{0,63}\Z")


def get_str_name(x):
    if not isinstance(x, str):
        raise Err("E_SCHEMA")
    if len(x) > 64:
        raise Err("E_LIMIT")
    if NAME_RE.match(x) is None:
        raise Err("E_SCHEMA")
    return x


def check_keys(obj, keys):
    chk(isinstance(obj, dict), "E_SCHEMA")
    if len(obj) != len(keys):
        raise Err("E_SCHEMA")
    for k in keys:
        chk(k in obj, "E_SCHEMA")


def parse_inputs(v):
    """validated rectangular P x R x D array -> (P, R, D, data)"""
    if type(v) is not list:
        raise Err("E_SCHEMA")
    P = len(v)
    if P < 1 or P > 8:
        raise Err("E_LIMIT")
    R = None
    for row in v:
        if type(row) is not list:
            raise Err("E_SCHEMA")
        if R is None:
            R = len(row)
        elif len(row) != R:
            raise Err("E_SCHEMA")
    if R > 128:
        raise Err("E_LIMIT")
    D = None
    for row in v:
        for vec in row:
            if type(vec) is not list:
                raise Err("E_SCHEMA")
            if D is None:
                D = len(vec)
            elif len(vec) != D:
                raise Err("E_SCHEMA")
    if D is None:
        D = 0
    if D > 32:
        raise Err("E_LIMIT")
    for row in v:
        for vec in row:
            if vec:
                if not all(type(x) is int for x in vec):
                    raise Err("E_SCHEMA")
                if min(vec) < -1000000000 or max(vec) > 1000000000:
                    raise Err("E_LIMIT")
    return P, R, D, v


def expected_sums(inp, P, R, D):
    """expected[q] = sum over all ranks of inputs[r][q]"""
    out = []
    for q in range(R):
        s = [0] * D
        for r in range(P):
            vec = inp[r][q]
            for i in range(D):
                s[i] += vec[i]
        out.append(s)
    return out


def parse_op(v):
    chk(isinstance(v, str), "E_SCHEMA")
    if v not in ("replay", "audit", "export"):
        raise Err("E_SCHEMA")
    return v


def parse_events(v, P, R):
    chk(isinstance(v, list), "E_SCHEMA")
    if len(v) > 20000:
        raise Err("E_LIMIT")
    out = []
    for ev in v:
        chk(isinstance(ev, list), "E_SCHEMA")
        chk(len(ev) >= 1, "E_SCHEMA")
        k = ev[0]
        if not isinstance(k, str) or k not in ("send", "retry", "deliver", "drop", "duplicate"):
            raise Err("E_SCHEMA")
        if k == "send":
            chk(len(ev) == 3, "E_SCHEMA")
            if not isint(ev[1]):
                raise Err("E_SCHEMA")
            chk(0 <= ev[1] < P, "E_LIMIT")
            if not isint(ev[2]):
                raise Err("E_SCHEMA")
            chk(0 <= ev[2] < R, "E_LIMIT")
        elif k == "retry":
            chk(len(ev) == 2, "E_SCHEMA")
            if not isint(ev[1]):
                raise Err("E_SCHEMA")
            chk(0 <= ev[1] < P, "E_LIMIT")
        else:
            chk(len(ev) == 2, "E_SCHEMA")
            if not isint(ev[1]):
                raise Err("E_SCHEMA")
            chk(0 <= ev[1] <= 200000, "E_LIMIT")
        out.append(ev)
    return out


def do_replay(inp, P, R, D, req):
    slotsn = req["slots"]
    window = req["window"]
    events = parse_events(req["events"], P, R)
    if not isint(slotsn):
        raise Err("E_SCHEMA")
    chk(1 <= slotsn <= 16, "E_LIMIT")
    if not isint(window):
        raise Err("E_SCHEMA")
    chk(1 <= window <= slotsn, "E_LIMIT")
